import json,collections
from pathlib import Path
out=Path(__file__).resolve().parent
load=lambda n:json.loads((out/n).read_text())
r=load('rows.json');emitters=load('emitters.json');diff=load('comparison.json');p=load('provenance.json');status=load('census-result.json')
def loc(f):return 'core.ts:'+f['where'].rsplit('/core.ts:',1)[1]
def esc(s):return str(s).replace('|','&#124;').replace('\n',' ')
def emit(f):return '; '.join(f"{e['file']}:{e['line']} `{e['function']}`" for e in emitters[f['id']])
counts=collections.Counter(u['reported_status'] for u in r['units']);added={f['id'] for f in diff['new']}
a=['# Full core.ts site census after the wave','','Task b5w3ycg. Report only, not for landing.','',f"Main/compiler/apply SHA: `{p['main_sha']}`. TypeScript 6.0.3: `{p['typescript_pin']}`.",'',f"Census child exit {status['exit_code']}; elapsed {status['seconds']:.3f} seconds. All of core.ts was selected with LATENT_FULL=1, LATENT_ONLY_FILE=/workspace/after-wave-adapted/src/compiler/core.ts, LATENT_ASSERT_NO_OUTPUT=1. No speculative or replay flags were set. Ordinary Load and Lower cannot return output in this guarded measurement binary.",'',f"Checker diagnostics: {len(r['measurement']['diagnostics'])}. Units: {len(r['units'])}; statuses: {dict(counts)}. Distinct location/kind/reason/phase sites: {len(r['sites'])}; first walls: {len(r['first_walls'])}.",'', 'The raw legacy label `measured on a checker-rejected program` is preserved even though this run has no checker diagnostics.', '', '## Every recorded site, in source order','', 'Repeated observations at the same location, kind, exact reason and phase share one F ID. `rows.json` retains all events and recording-unit identities. Emitters are pinned compiler source lines; `emitters.json` retains their exact source text and enclosing deciding function.','', '| Site | Location | Unit | Kind | Exact reason | Phase | Emitting lowering line and deciding function | First wall | Diff |','| --- | --- | --- | --- | --- | --- | --- | --- | --- |']
for f in r['sites']:
 a.append('| '+' | '.join([f['id'],loc(f),esc(f['site_unit_name']),f['kind'],esc(f['reason']),f['phase'],emit(f),'yes' if f['id'] in r['first_walls'] else 'no','new to inventory' if f['id'] in added else 'remains'])+' |')
a+=['','## First-wall list','', 'The list uses the 4186581e report\'s criterion: every refusal/contract scan finding, plus lowering findings outside deferred generic bodies, including signature-only overload checks. This is a source-order inventory, not a proven sequence of ordinary first stops after hypothetical repairs. Refusal-scan priority and statement rollback can change which stop wins or which downstream missing-local findings survive. A deferred body without a finding is not proven to lower.','']
for i,id in enumerate(r['first_walls'],1):
 f=next(f for f in r['sites'] if f['id']==id);a.append(f"{i}. {id}, `{loc(f)}`, {f['kind']}: {f['reason']} ({f['phase']}).")
a+=['','## Diff against the 4186581e report\'s 48 sites','',f"Gone: {len(diff['gone'])}. Remain: {len(diff['remain'])}. New to this inventory: {len(diff['new'])}.",'',diff['method'],'', 'A match means the same observed blocker remains; it does not assert unchanged runtime reach. Sites earlier than the former getOwnValues range are explicitly newly surveyed, rather than claimed regressions.','', '| Previous ID | Previous location | Unit | Kind | Exact reason | Phase | Result |','| --- | --- | --- | --- | --- | --- | --- |']
old=load('previous-rows.json');remaining={x['old']['id']:x['new'] for x in diff['remain']}
for f in old['sites']:
 n=remaining.get(f['id']);result='gone' if n is None else n['id']+' at '+loc(n)
 a.append('| '+' | '.join([f['id'],loc(f),esc(f['site_unit_name']),f['kind'],esc(f['reason']),f['phase'],result])+' |')
a+=['','New sites: '+(', '.join(f['id']+' at '+loc(f) for f in diff['new']) or 'none')+'.','','## Evidence and reproduction','','Both runs used the same frozen full apply. `adapted-source-manifest.json`, `adapted-product.manifest.json`, `core.ts.txt` and `provenance.json` identify its exact bytes. `validation.json` checks the source stayed unchanged. Raw core census, unit timings and census log are in `raw-streams.tar.gz`, with `raw-streams.tar.gz.sha256`. The previous 48-site report and machine-readable rows are retained for the diff.','','The overlay is generated by the pinned meter tools through `../next-stops-af42d3dc/build-entry.py`. This changes only physical scratch filenames to .go.txt. No production compiler source is modified. `run-census.py` retains the exact flags, process bounds and cleanup. `ast-map.cjs` and `analyze.py` retain declaration attribution and first-wall selection.','','```sh','source /workspace/adamic-tools/env.sh','python3 stage3/census/core-sites-af42d3dc/run-census.py > core-runner.log 2>&1','node stage3/census/core-sites-af42d3dc/ast-map.cjs > ast-map.log 2>&1','python3 stage3/census/core-sites-af42d3dc/analyze.py > analysis.log 2>&1','python3 stage3/census/core-sites-af42d3dc/map-emitters.py > emitter-map.log 2>&1','python3 stage3/census/core-sites-af42d3dc/compare-sites.py > site-comparison.log 2>&1','```','']
(out/'REPORT.md').write_text('\n'.join(a));(out/'first-walls.json').write_text(json.dumps([f for f in r['sites'] if f['id'] in r['first_walls']],indent=2)+'\n');print('report written')
